export const REQUEST_TIMEOUT_MS = resolveTimeoutMs(process.env.DELIVERY_TIMEOUT_MS);

export async function sendDelivery(url: string, body: string, signature: string): Promise<Response> {
  return fetch(url, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-tallyhook-signature': signature,
    },
    body,
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });
}

export async function processDelivery(deliveryId: string): Promise<void> {
  const delivery = await prisma.delivery.findUniqueOrThrow({
    where: { id: deliveryId },
    include: { endpoint: true },
  });
  const { endpoint } = delivery;
  if (endpoint.disabledAt) {
    return;
  }
  if (isQuietHours(DEFAULT_QUIET_WINDOW)) {
    // hold until the window closes; the scheduler picks it up again
    return;
  }

  const body = JSON.stringify(delivery.payload);
  const signature =
    endpoint.signingVersion === 2
      ? signPayloadV2(endpoint.secret, body, Math.floor(Date.now() / 1000))
      : signPayload(endpoint.secret, body);
  const attempt = delivery.attempts + 1;

  try {
    const res = await sendDelivery(endpoint.url, body, signature);
    if (!res.ok) {
      throw new Error(`endpoint responded ${res.status}`);
    }
    await prisma.delivery.update({
      where: { id: delivery.id },
      data: { status: 'SUCCEEDED', attempts: attempt, lastError: null },
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (shouldRetry(attempt, endpoint.maxRetries)) {
      await prisma.delivery.update({
        where: { id: delivery.id },
        data: {
          status: 'FAILED',
          attempts: attempt,
          lastError: message,
          nextAttemptAt: new Date(Date.now() + backoffDelay(attempt)),
        },
      });
    } else {
      await prisma.delivery.update({
        where: { id: delivery.id },
        data: { status: 'DEAD', attempts: attempt, lastError: message },
      });
      logger.warn({ deliveryId, endpointId: endpoint.id }, 'delivery dead-lettered');
    }
  }
}

import { describe, it, expect, vi, afterEach } from 'vitest';

vi.mock('@tallyhook/shared', () => ({
  prisma: {},
  logger: { warn: vi.fn(), info: vi.fn(), error: vi.fn() },
  backoffDelay: () => 1000,
  shouldRetry: () => true,
}));

import { sendDelivery, resolveTimeoutMs } from './deliver';

describe('sendDelivery', () => {
  afterEach(() => vi.unstubAllGlobals());

  it('sends the signature header and JSON body', async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response(null, { status: 204 }));
    vi.stubGlobal('fetch', fetchMock);

    await sendDelivery('https://example.com/hook', '{"a":1}', 'abc123');

    const [url, init] = fetchMock.mock.calls[0] as [
      string,
      RequestInit & { headers: Record<string, string> },
    ];
    expect(url).toBe('https://example.com/hook');
    expect(init.headers['x-tallyhook-signature']).toBe('abc123');
    expect(init.body).toBe('{"a":1}');
  });
});

describe('resolveTimeoutMs', () => {
  it('falls back to 10s for missing or invalid values', () => {
    expect(resolveTimeoutMs(undefined)).toBe(10_000);
    expect(resolveTimeoutMs('abc')).toBe(10_000);
    expect(resolveTimeoutMs('-5')).toBe(10_000);
    expect(resolveTimeoutMs('30000')).toBe(30_000);
  });
});
